// Chart page behaviour. The grids, tables, and the first stroke diagram are
// static HTML generated by scripts/build_site.py; this file only adds audio,
// stroke animation, and printing.
const cache = new Map();
let currentAudio = null;

function stopAudio() {
  if (currentAudio) { try { currentAudio.pause(); } catch (e) {} currentAudio = null; }
  if (window.speechSynthesis) { try { window.speechSynthesis.cancel(); } catch (e) {} }
}
function play(audioName, fallback) {
  stopAudio();
  const audio = new Audio("/audio/" + audioName + ".mp3");
  currentAudio = audio;
  const run = audio.play();
  if (run && run.catch) run.catch(() => speak(fallback || audioName));
  audio.addEventListener("error", () => speak(fallback || audioName), { once: true });
}
function speak(text) {
  if (!window.speechSynthesis) return;
  const u = new SpeechSynthesisUtterance(text);
  u.lang = "ja-JP";
  window.speechSynthesis.speak(u);
}
function strokeNo(id) {
  const m = /[dc](\d+)[a-z]?\)?$/.exec(id || "");
  return m ? Number(m[1]) : 0;
}
function firstPoint(d) {
  const m = /M\s*(-?\d+(?:\.\d+)?)\s*,?\s*(-?\d+(?:\.\d+)?)/.exec(d || "");
  return m ? [Number(m[1]), Number(m[2])] : null;
}
async function loadSvg(kana) {
  const code = kana.codePointAt(0);
  if (cache.has(code)) return cache.get(code);
  let text = "";
  try { const res = await fetch("/strokes/" + code + ".svg"); if (res.ok) text = await res.text(); } catch (e) {}
  cache.set(code, text);
  return text;
}
function buildSvg(text) {
  if (!text) return { svg: null, count: 0 };
  const doc = new DOMParser().parseFromString(text, "image/svg+xml");
  const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
  svg.setAttribute("viewBox", "0 0 1024 1024");
  const shapes = [...doc.querySelectorAll("path[id]")].filter((p) => strokeNo(p.id));
  const lines = [...doc.querySelectorAll("path[clip-path]")];
  const starts = new Map();
  lines.forEach((p) => {
    const no = strokeNo(p.getAttribute("clip-path"));
    const pt = firstPoint(p.getAttribute("d"));
    if (no && pt && pt[0] >= 0 && !starts.has(no)) starts.set(no, pt);
  });
  const numbers = [...new Set(shapes.map((p) => strokeNo(p.id)))].sort((a, b) => a - b);
  numbers.forEach((no, index) => {
    shapes.filter((p) => strokeNo(p.id) === no).forEach((p) => {
      const d = document.createElementNS("http://www.w3.org/2000/svg", "path");
      d.setAttribute("d", p.getAttribute("d"));
      d.setAttribute("class", "glyph-stroke");
      d.style.animationDelay = (index * 0.7) + "s";
      svg.appendChild(d);
    });
    const pt = starts.get(no);
    if (!pt) return;
    const badge = document.createElementNS("http://www.w3.org/2000/svg", "g");
    badge.setAttribute("class", "stroke-badge");
    badge.style.animationDelay = (index * 0.7) + "s";
    badge.innerHTML = '<circle cx="' + pt[0] + '" cy="' + pt[1] + '" r="36"/><text x="' + pt[0] + '" y="' + (pt[1] + 12) + '" text-anchor="middle">' + no + '</text>';
    svg.appendChild(badge);
  });
  return { svg, count: numbers.length };
}

const stage = document.getElementById("glyph");
const reading = document.getElementById("reading");
const order = document.getElementById("order");
const charLink = document.getElementById("char-link");
let current = null;

async function show(cell, silent) {
  current = cell;
  const d = cell.dataset;
  reading.textContent = silent ? "" : d.romaji;
  if (charLink) {
    charLink.href = d.href;
    charLink.textContent = "Open the " + d.kana + " page: stroke order, words, and tips";
  }
  if (!silent) play(d.audio, d.kana);
  const parts = d.base ? [d.base, d.small] : [d.kana];
  const built = [];
  for (const ch of parts) built.push(buildSvg(await loadSvg(ch)));
  if (current !== cell) return;
  stage.innerHTML = "";
  if (built.every((b) => b.svg && b.count)) {
    if (built.length === 2) {
      built[0].svg.classList.add("glyph-base");
      built[1].svg.classList.add("glyph-small");
      const delay = built[0].count * 0.7;
      built[1].svg.querySelectorAll(".glyph-stroke, .stroke-badge").forEach((el) => {
        el.style.animationDelay = ((parseFloat(el.style.animationDelay) || 0) + delay) + "s";
      });
    }
    built.forEach((b) => stage.appendChild(b.svg));
    const total = built.reduce((n, b) => n + b.count, 0);
    order.textContent = total + (total === 1 ? " stroke" : " strokes");
  } else {
    stage.textContent = d.kana;
    order.textContent = "Stroke order animation is not available. Audio only.";
  }
}

let looping = true;
document.querySelectorAll(".cell").forEach((cell) => {
  cell.addEventListener("click", () => { looping = false; show(cell, false); });
});
document.getElementById("play").addEventListener("click", () => {
  if (current) play(current.dataset.audio, current.dataset.kana);
});
document.getElementById("replay-strokes").addEventListener("click", () => {
  if (current) show(current, true).then(() => { if (!looping) reading.textContent = current.dataset.romaji; });
});
document.querySelectorAll(".word-btn").forEach((el) => {
  el.addEventListener("click", () => play(el.dataset.audio, el.textContent));
});
const printBtn = document.getElementById("print");
if (printBtn) printBtn.addEventListener("click", () => {
  looping = false;
  document.body.classList.add("print-table");
  setTimeout(() => {
    window.print();
    document.body.classList.remove("print-table");
  }, 80);
});

// Old links: /#katakana now has its own page.
const hash = (location.hash || "").replace("#", "");
if (hash === "katakana" && document.body.dataset.script === "hiragana") location.replace("/katakana-chart");
function openSpecial() {
  const el = document.getElementById("special");
  if (location.hash === "#special" && el) el.open = true;
}
window.addEventListener("hashchange", openSpecial);
openSpecial();

// Idle loop: replay the first character's strokes without sound.
const first = document.querySelector("#grid .cell");
if (first) {
  current = first;
  const replay = () => {
    if (!looping) return;
    show(first, true);
    setTimeout(replay, 2600 + 700 * (first.dataset.base ? 6 : 3));
  };
  setTimeout(replay, 2600);
}
